# Pulumi ComponentResource: Service Infrastructure Wrapper

Here's a complete ComponentResource implementation in TypeScript that wraps an S3 bucket, RDS PostgreSQL instance, and IAM role, with dev/prod configuration support.

## Main Component: `service-component.ts`

```typescript
import * as aws from "@pulumi/aws";
import * as pulumi from "@pulumi/pulumi";

export interface ServiceComponentArgs {
  environment: "dev" | "prod";
  region?: string;
  dbName?: string;
  dbUsername?: string;
  vpcId?: pulumi.Input<string>;
}

export class ServiceComponent extends pulumi.ComponentResource {
  public readonly bucket: aws.s3.Bucket;
  public readonly rdsInstance: aws.rds.Instance;
  public readonly rdsSecurityGroup: aws.ec2.SecurityGroup;
  public readonly iamRole: aws.iam.Role;
  public readonly bucketName: pulumi.Output<string>;
  public readonly rdsEndpoint: pulumi.Output<string>;
  public readonly roleArn: pulumi.Output<string>;

  constructor(
    name: string,
    args: ServiceComponentArgs,
    opts?: pulumi.ComponentResourceOptions
  ) {
    super("service:aws:Component", name, {}, opts);

    const config = new pulumi.Config();
    const env = args.environment;
    const region = args.region || aws.getRegionOutput().name;

    // ============================================================================
    // 1. S3 BUCKET: Versioning + Encryption + No Public Access
    // ============================================================================
    this.bucket = new aws.s3.Bucket(
      `${name}-bucket`,
      {
        acl: "private",
        versioning: {
          enabled: true,
        },
        serverSideEncryptionConfiguration: {
          rule: {
            applyServerSideEncryptionByDefault: {
              sseAlgorithm: env === "prod" ? "aws:kms" : "AES256",
              kmsMasterKeyId:
                env === "prod"
                  ? config.get("kmsKeyId") // Must be set in prod stack config
                  : undefined,
            },
            bucketKeyEnabled: true,
          },
        },
        publicAccessBlockConfiguration: {
          blockPublicAcls: true,
          blockPublicPolicy: true,
          ignorePublicAcls: true,
          restrictPublicBuckets: true,
        },
        // Prod only: cross-region replication
        ...(env === "prod"
          ? {
              replicationConfiguration: {
                role: new aws.iam.Role(
                  `${name}-s3-replication-role`,
                  {
                    assumeRolePolicy: aws.iam
                      .getPolicyDocument(
                        {
                          statements: [
                            {
                              principals: [
                                {
                                  type: "Service",
                                  identifiers: ["s3.amazonaws.com"],
                                },
                              ],
                              actions: ["sts:AssumeRole"],
                              effect: "Allow",
                            },
                          ],
                        },
                        { async: true }
                      )
                      .then((p) => p.json),
                  },
                  { parent: this }
                ).arn,
                rules: [
                  {
                    id: "replicate-all",
                    status: "Enabled",
                    priority: 1,
                    deleteMarkerReplication: {
                      enabled: true,
                    },
                    filter: {
                      prefix: "",
                    },
                    destinations: [
                      {
                        bucket: pulumi.interpolate`arn:aws:s3:::${name}-replica-us-west-2`,
                        replicationTime: {
                          status: "Enabled",
                          time: 15,
                        },
                        metrics: {
                          status: "Enabled",
                          eventThreshold: 15,
                        },
                      },
                    ],
                  },
                ],
              },
            }
          : {}),
        tags: {
          Environment: env,
          ManagedBy: "Pulumi",
          Component: name,
        },
      },
      { parent: this }
    );

    this.bucketName = this.bucket.id;

    // ============================================================================
    // 2. RDS POSTGRESQL: Deletion Protection + Encryption + Multi-AZ in Prod
    // ============================================================================

    // Fetch default VPC and subnets for DB subnet group
    const defaultVpc = pulumi
      .output(aws.ec2.getVpc({ default: true }))
      .apply((v) => v.id);
    const vpcSubnets = pulumi
      .output(aws.ec2.getSubnets({ filters: [] }))
      .apply((s) => s.ids.slice(0, 2)); // At least 2 for multi-AZ

    const dbSubnetGroup = new aws.rds.SubnetGroup(
      `${name}-db-subnet-group`,
      {
        subnetIds: vpcSubnets,
        tags: {
          Environment: env,
        },
      },
      { parent: this }
    );

    // RDS Security Group
    this.rdsSecurityGroup = new aws.ec2.SecurityGroup(
      `${name}-rds-sg`,
      {
        vpcId: args.vpcId || defaultVpc,
        ingress: [
          {
            protocol: "tcp",
            fromPort: 5432,
            toPort: 5432,
            cidrBlocks: ["10.0.0.0/8"], // Restrict to internal CIDR
          },
        ],
        egress: [
          {
            protocol: "-1",
            fromPort: 0,
            toPort: 0,
            cidrBlocks: ["0.0.0.0/0"],
          },
        ],
        tags: {
          Environment: env,
        },
      },
      { parent: this }
    );

    // RDS Instance with environment-specific sizing
    const dbPassword = config.requireSecret("dbPassword");
    const dbInstanceClass = env === "prod" ? "db.t3.medium" : "db.t3.micro";
    const allocatedStorage = env === "prod" ? 100 : 20;

    this.rdsInstance = new aws.rds.Instance(
      `${name}-rds`,
      {
        identifier: `${name}-db-${env}`,
        engine: "postgres",
        engineVersion: "15.4",
        instanceClass: dbInstanceClass,
        allocatedStorage: allocatedStorage,
        storageEncrypted: env === "prod",
        storageType: "gp3",
        iops: env === "prod" ? 3000 : undefined,
        dbName: args.dbName || "appdb",
        username: args.dbUsername || "postgres",
        password: dbPassword,
        parameterGroupName: aws.rds
          .getParameterGroupOutput({
            name: "default.postgres15",
          })
          .apply((pg) => pg.name),
        dbSubnetGroupName: dbSubnetGroup.name,
        vpcSecurityGroupIds: [this.rdsSecurityGroup.id],
        multiAz: env === "prod",
        deletionProtection: env === "prod",
        backupRetentionPeriod: env === "prod" ? 30 : 7,
        backupWindow: "03:00-04:00",
        maintenanceWindow: "sun:04:00-sun:05:00",
        skipFinalSnapshot: env === "dev",
        finalSnapshotIdentifierPrefix: env === "prod" ? `${name}-final` : undefined,
        publiclyAccessible: false,
        enableIamDatabaseAuthentication: env === "prod",
        enableCloudwatchLogsExports: ["postgresql"],
        tags: {
          Environment: env,
          ManagedBy: "Pulumi",
          Component: name,
        },
      },
      { parent: this }
    );

    this.rdsEndpoint = this.rdsInstance.endpoint;

    // ============================================================================
    // 3. IAM ROLE: Least Privilege Service Account Role
    // ============================================================================

    const trustPolicy: aws.iam.PolicyDocument = {
      Version: "2012-10-17",
      Statement: [
        // EC2 trust for direct EC2 instance profiles
        {
          Action: "sts:AssumeRole",
          Effect: "Allow",
          Principal: {
            Service: "ec2.amazonaws.com",
          },
        },
        // Prod only: OIDC trust for IRSA (IAM Roles for Service Accounts)
        ...(env === "prod"
          ? [
              {
                Action: "sts:AssumeRoleWithWebIdentity",
                Effect: "Allow",
                Principal: {
                  Federated: config.get("oidcProviderArn") || "",
                },
                Condition: {
                  StringEquals: {
                    "oidc.eks.*.amazonaws.com/id/*:sub":
                      "system:serviceaccount:*:app-service",
                  },
                },
              },
            ]
          : []),
      ],
    };

    this.iamRole = new aws.iam.Role(
      `${name}-service-role`,
      {
        assumeRolePolicy: pulumi.output(trustPolicy).apply(JSON.stringify),
        tags: {
          Environment: env,
        },
      },
      { parent: this }
    );

    // Least-privilege inline policy
    const policyDocument: aws.iam.PolicyDocument = {
      Version: "2012-10-17",
      Statement: [
        {
          Sid: "S3BucketAccess",
          Effect: "Allow",
          Action: [
            "s3:GetObject",
            "s3:PutObject",
            "s3:DeleteObject",
          ],
          Resource: [pulumi.interpolate`${this.bucket.arn}/*`],
          // Prod: explicitly deny wildcards to enforce granularity
          ...(env === "prod"
            ? {
                Condition: {
                  StringNotLike: {
                    "s3:key": "*",
                  },
                },
              }
            : {}),
        },
        {
          Sid: "S3ListBucket",
          Effect: "Allow",
          Action: ["s3:ListBucket"],
          Resource: [this.bucket.arn],
        },
        {
          Sid: "RDSDatabaseConnect",
          Effect: "Allow",
          Action: ["rds-db:connect"],
          Resource: pulumi.interpolate`arn:aws:rds:${region}:${aws.getCallerIdentityOutput().accountId}:db:${this.rdsInstance.identifier}`,
        },
      ],
    };

    new aws.iam.RolePolicy(
      `${name}-service-policy`,
      {
        role: this.iamRole.id,
        policy: pulumi.output(policyDocument).apply(JSON.stringify),
      },
      { parent: this }
    );

    this.roleArn = this.iamRole.arn;

    // Register outputs for external reference
    this.registerOutputs({
      bucketName: this.bucketName,
      bucketArn: this.bucket.arn,
      rdsEndpoint: this.rdsEndpoint,
      rdsIdentifier: this.rdsInstance.identifier,
      rdsPort: this.rdsInstance.port,
      roleArn: this.roleArn,
      roleName: this.iamRole.name,
    });
  }
}
```

## Usage in `index.ts`

```typescript
import * as pulumi from "@pulumi/pulumi";
import { ServiceComponent } from "./service-component";

const config = new pulumi.Config();
const environment = pulumi.getStack() as "dev" | "prod";

const serviceComponent = new ServiceComponent("app", {
  environment,
  region: config.get("region") || "us-east-1",
  dbName: config.get("dbName") || "appdb",
  dbUsername: config.get("dbUsername") || "postgres",
});

export const bucketName = serviceComponent.bucketName;
export const rdsEndpoint = serviceComponent.rdsEndpoint;
export const roleArn = serviceComponent.roleArn;
```

## Stack Configuration: `Pulumi.dev.yaml`

```yaml
config:
  aws:region: us-east-1
  dbPassword:
    secure: AAABAxxxxx...  # pulumi config set --secret dbPassword <password>
  dbName: appdb
  dbUsername: postgres
```

## Stack Configuration: `Pulumi.prod.yaml`

```yaml
config:
  aws:region: us-east-1
  dbPassword:
    secure: AAABAxxxxx...  # Different secret, never shared
  dbName: appdb_prod
  dbUsername: postgres
  kmsKeyId: arn:aws:kms:us-east-1:ACCOUNT:key/12345678-...
  oidcProviderArn: arn:aws:iam::ACCOUNT:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/ABCD1234567890
```

## Deployment

```bash
# Deploy to dev
pulumi stack select dev
pulumi up

# Deploy to prod (independent state, requires different secrets)
pulumi stack select prod
pulumi config set --secret dbPassword <prod-password>
pulumi up
```

## Key Features

✅ **Acceptance Criteria Met:**
- S3: versioning, encryption (AES-256 for dev, KMS for prod), no public access
- RDS: deletion protection (prod), ≥7 day backups, not publicly accessible, multi-AZ in prod
- IAM: least privilege, no wildcard actions in prod, OIDC trust in prod only
- Secrets: ConfigSecret encryption via `--secret` flag, never in plaintext
- Environment isolation: separate stacks with independent state files

✅ **Idiomatic Pulumi:**
- ComponentResource pattern for composition
- Stack config for environment differentiation (not build-time parameters)
- Proper parent–child relationships for logical grouping
- Output registration for downstream consumption
